SELECT
    month ,SUM(value) AS metricsValue, '${year}' AS year, '${metricsName}' AS metricsName
FROM bi_target_staff_setting tss
LEFT JOIN bi_target_year ty
ON tss.main_id=ty.id and ty.is_deleted=false
WHERE tss.is_deleted=false AND ty.year=#{year}
AND tss.metrics=#{metrics}

    AND ty.dept_id IN

        #{deptId}


GROUP BY month

SELECT month, SUM (value) AS metricsValue, '${year}' AS year, '${metricsName}' AS metricsName FROM bi_target_staff_setting tss LEFT JOIN bi_target_year ty ON tss.main_id=ty.id and ty.is_deleted= false WHERE tss.is_deleted= false AND ty.year=#{year} AND tss.metrics=#{metrics}
AND tss.staff_id IN
#{staffId}
GROUP BY month

